  pe = `Защо виждам това?`,
  me = `%1$s от приложенията Ви е включено в тази страница за разпродажба. Ако никой не се е свързал с Вас относно присъединяването към това събитие, моля, обърнете се към организатора на събитието.`,
  he = `%1$s от приложенията Ви са включени в тази страница за разпродажба. Ако не сме се свързали с Вас относно присъединяването към това събитие, моля, обърнете се към организатора на събитието.`,
