  ye = `Брутни продажби`,
  be = `Общата сума от продажбите на всички пакети за всички приложения в разпродажбата, през целия период, обхванат от разпродажбата.`,
  xe = `Пакети с някакви отстъпки`,
  Se = `Общата сума от продажбите на всички пакети с някакви отстъпки за всички приложения в разпродажбата. Това покрива целия период, обхванат от разпродажбата.`,
  Ce = `Вижте подробностите`,
