  Pe = `Всяко приложение, описано директно или чрез пакет/комплект. Статистиките обхващат всички пакети, съдържащи това приложение.`,
  Fe = `Пакети от списъка`,
  Ie = `Всеки пакет, участващ в разпродажбата (игнорира пакети, указани само от комплект или включено приложение)`,
  Le = `Комплекти от списъка`,
