  jm = `За едно от Вашите приложения липсва немска възрастова оценка. Считано от 15 ноември 2024 нататък, Steam вече няма да изобразява това заглавие на клиенти, преглеждащи Steam магазина в Германия. С цел да се уверите, че игрите Ви са достъпни за продажба в Германия, моля, попълнете и публикувайте вградения въпросник за съдържание на Steam.`,
  Mm = `За редица от Вашите приложения липсват немски възрастови оценки. Считано от 15 ноември 2024 нататък, Steam вече няма да изобразява тези заглавия на клиенти, преглеждащи Steam магазина в Германия. С цел да се уверите, че игрите Ви са достъпни за продажба в Германия, моля, попълнете и публикувайте вградения въпросник за съдържание на Steam.`,
