  O_ = `Ако играта Ви съдържа клиентско или сървърно противодействие на измами, което не е базирано на ниво ядро на ОС, това поле не е задължително. Но обикновено считаме, че всяко заглавие, което използва технология за противодействие на измами, би имало полза от това да уведоми играчите.`,
