  av = `Този интерфейс Ви позволява да предоставите изображение, което описва разликата между изданията на Вашата игра (напр. стандартно с/у луксозно с/у игра на годината и т.н.). Изданията ще бъдат групирани с основната игра в най-горната част на опциите за закупуване и сортирани от най-ниската към най-високата цена на страницата в магазина. За още подробности, моля, вижте <1>документацията за управление на изданията</1>.`,
