  fb = `Това ще добави художествено творчество за капсула към изобразяването за покупка на пакета в магазина. Това е сходно с начина, по който се изобразява съдържанието на комплектите. Основното приложение ще бъде показвано първо, а след това и останалите включени приложения от най-висока към най-ниска цена.`,
