  gj = `Афишно изображение за отличено видео`,
  _j = `Фоново изображение за отличено видео`,
  vj = `Начална страница — Превземане | Статично худ. творчество`,
  yj = `Начална страница — Превземане | Анимирано (webm)`,
  bj = `Начална страница — Превземане | Анимация (mp4)`,
  xj = `Начална страница — Превземане | Мобилно худ. творчество`,
  Sj = `Начална страница — Превземане | Мобилно анимирано (webm)`,
  Cj = `Начална страница — Превземане | Мобилна анимация (mp4)`,
  wj = `Начална страница — Подвземане | Статично худ. творчество`,
  Tj = `Начална страница — Подвземане | Мобилно худ. творчество`,
  Ej = `Фоново изображение за разпродажба`,
  Dj = `Лого на страница за разпродажба`,
