  DX = `Постижения`,
  OX = `Набори от постижения`,
  kX = `Грешки (%1$s файлове)`,
  AX = `Грешки (%1$s файл)`,
  jX = `Грешки (%1$s файлове)`,
  MX = `Успешно (%1$s файл)`,
  NX = `Успешно (%1$s файла)`,
  PX = `Следните файлове имаха грешки. Можете да ги премахнете или да ги внесете отново, след като поправите всякакви грешки.`,
  FX = `Следните файлове бяха успешно внесени.`,
  IX = `CSV определения за постижения`,
  LX = `Определяне и редактиране на постиженията в играта. Без определени постижения, изнесеният файл е шаблон с няколко реда „EXAMPLE_ “ в него. Въведете текст върху тях, изтрийте ги или качете шаблона както е, за да видите как работи внасянето.`,
  RX = `Вече определени — %1$s`,
  zX = `Понастоящем поддържани — %1$s`,
  BX = `Локализация на постиженията (CSV)`,
  VX = `Редактирайте имената и описанията за определени постижения на езиците, конфигурирани за играта Ви.`,
  HX = `<1>СЪВЕТ: Започвате ли с локализацията?</1> Първо конфигурирайте очакваните езици, така че CSV файлът да включва тези езикови заглавни части, локализирайте и след това качете попълнения CSV файл по-долу.`,
  UX = `Конфигуриране на езици`,
  WX = `Локализация на набор от постижения (CSV)`,
  GX = `Редактирайте имената за наборите Ви на постижения на езиците, конфигурирани за Вашата игра. Самите набори трябва първо да бъдат създадени в редактора.`,
  KX = `Изнасяне на локализация за набор (.csv)`,
  qX = `Вече определени — %1$s`,
  JX = ` Икони на постижения`,
  YX = `С цел да свържете автоматично иконата със свързаното постижение, наименувайте файловете за изображенията с името на постижението в приложно програмния интерфейс и суфикса „_ACHIEVED“ или „_UNACHIEVED“. Например: „LEVEL_20_ACHIEVED.png“.`,
  XX = `изисквано, уникално; името, което играта Ви предава към приложно програмния интерфейс`,
  ZX = `незадължително; № на набор, който вече съществува`,
  QX = `едно от %1$s`,
  $X = `true или false`,
  eZ = `незадължително; името на вече съществуваща статистика, оставя се празно при липса на лента за напредък`,
  tZ = `число, не по-ниско от собствения минимум на статистиката`,
  nZ = `число, над минимума и не по-високо от собствения максимум на статистика`,
  rZ = `задължително; трябва да съответства на „api_name“ от CSV определенията`,
  iZ = `наименование или описание`,
  aZ = `задължително; № на набор, който вече съществува`,
  oZ = `Внасяне на постижения от CSV`,
  sZ = `Провлечете .csv файл с постижения тук, за да го качите`,
  cZ = `Ред`,
  lZ = `Поле`,
  uZ = `Въвеждане`,
  dZ = `Грешка`,
  fZ = `За добавяне (%1$s)`,
  pZ = `Постиженията, които не съответстват на съществуващо име на приложно програмен интерфейс, са изброени тук. На тях ще бъде възложен нов № за постижение. Ако възнамерявате да промените дадено съществуващо име на приложно програмен интерфейс, моля, първо направете тези изменения в редактора.`,
  mZ = `Липсващо от CSV (%1$s)`,
  hZ = `Постиженията, които предходно сте определили, но не са били намерени във внесения CSV файл, са изброени тук. Те ще останат, освен ако отметнете полето по-долу, за да ги изтриете.`,
  gZ = `Изтриване на тези постижения`,
  _Z = `За модифициране (%1$s)`,
  vZ = `Постиженията, които са били модифицирани, са изброени тук. Те ще бъдат обновени.`,
  yZ = `Немодифицирани (%1$s)`,
  bZ = `Немодифицираните постижения са изброени тук. Те няма да бъдат обновени.`,
  xZ = `Липсващо изображение за постижение`,
  SZ = `Невалидно CSV: Всички добавени постижения трябва да се отнасят към статистики в един и същ набор (или от този по подразбиране).`,
  CZ = `Невалидно име на приложно програмен интерфейс: Имената трябва да са уникални.`,
  wZ = `Засечени грешки във внесения CSV файл. Моля, поправете посочените по-долу грешки, а след това качете файла пак.`,
  TZ = `Посочва промяна`,
  EZ = `№ на набор`,
  DZ = `Наборите, чиито имена са били променени, са изброени тук. Те ще бъдат обновени.`,
  OZ = `Немодифицираните набори са изброени тук. Те няма да бъдат обновени.`,
  kZ = `Невалиден № на набор — № на набори трябва да бъдат уникални`,
  AZ = `Невалиден № на набор — Наборът с постижения за същинската игра не може да бъде преименуван`,
  jZ = `Неочаквана колона — Не се поддържа %1$s език`,
  MZ = `Невалидно име — Наборите трябва да имат име на английски език`,
  NZ = `Невалидно име на статистика: Статистиката не съществува. Първо <1>редактирайте своите статистики</1>, за да създадете нови.`,
  PZ = `Невалидно правомощие: Постиженията и статистиките трябва да разполагат с едно и също правомощие.`,
  FZ = `Невалидно цяло число: Стойността трябва да бъде цяло число, когато статистиката е от целочислен тип.`,
  IZ = `Невалиден диапазон за напредък: Максимумът трябва да бъде по-голям от минимума.`,
