  VZ = `Наборът по подразбиране не може да се мести.`,
  HZ = `Опции`,
  UZ = `Ширината и височината на изображението трябва да са с еднакъв размер`,
  WZ = `Размерите на изображението трябва да бъдат поне %1$s x %1$s`,
  GZ = `Неизвестен тип съдържание`,
